float SceneSDF(vec3 Point)
{
    vec3 CellIndex = floor(Point / CellSize);
    vec3 CellPos = CellIndex * CellSize + CellSize * .5;

    // xyz are offsets w is the radius (if its below the treshold there wont be a sphere)
    vec4 Sphere = hash43(CellIndex);

    //move and normalize offset to be between -CellSize * .25 and +CellSize * .25
    vec3 OffsetByTime = vec3(
        cos(iTime * SphereOffsetSpeed + CellIndex.x * CellMovementDist),
        cos(iTime * SphereOffsetSpeed * .8 + CellIndex.y * CellMovementDist),
        cos(iTime * SphereOffsetSpeed * .9 + CellIndex.z * CellMovementDist)
    );
    Sphere.xyz = ((Sphere.xyz + OffsetByTime) - .5) / 6. * CellSize;

    // everything bellow the sphere treshold will be negative and everything above will be normalised between 0 and SphereMaxRadius
    Sphere.w -= SphereTreshold;
    Sphere.w /= 1. - SphereTreshold;
    Sphere.w *= SphereMaxRadius;

    // if the sphere is too big to fit into the cell due to its offset change its radius
    Sphere.w = min(Sphere.w, min(CellSize * .5 - abs(Sphere.x), min(CellSize * .5 - abs(Sphere.y), CellSize * .5 - abs(Sphere.z))));

    // add the cell position to sphere xyz and multiply sphere offset by SphereMaxOffset
    Sphere.xyz = Sphere.xyz * SphereMaxOffset + CellPos;

    float SphereDist = length(Point - Sphere.xyz) - Sphere.w; // Sphere sdf

    return min(SphereDist, MaxStepDist);
}

vec3 March(vec3 RayOrigin, vec3 RayDir)
{
    vec3 Pos = RayOrigin;
    float TotalDist = 0.;
    float Closest = MaxDist;
    float ClosestPointDist = 0.;

    for (int i = 0; i < MaxIteration; i++)
    {
        float Dist = SceneSDF(Pos + RayDir * TotalDist);
        TotalDist += min(Dist, 2.);
        Closest = min(Closest, Dist);

        if (Closest == Dist) ClosestPointDist = TotalDist;

        if (TotalDist > MaxDist || abs(Dist) < MinDist) break;
    }

    return vec3(length(Pos + RayDir * TotalDist - RayOrigin), Closest, ClosestPointDist);
}


void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = (fragCoord - iResolution.xy * .5) / iResolution.y;

    vec3 RayDir = normalize(vec3(uv, 1));

    vec3 Marched = March(CamPos, RayDir);
    float col = 1. - Marched.y;
    col *= col;

    col = smoothstep(.3, 1., col) * smoothstep(1., .8, col);
    col *= smoothstep(1., 0., Marched.z / MaxDist);

    vec3 Gradient = mix(vec3(.7, .2, .9), vec3(.3, 1., .8), uv.x * .1 + .1 + uv.y * .3 + .3);

    // Output to screen
    fragColor = vec4(vec3(col) * Gradient + Gradient * Marched.x / MaxDist * .8,1.0);
}

#define MaxIteration 200
#define MaxDist 50.
#define MaxStepDist .5
#define MinDist .01

#define CellSize 4.
#define CellMovementDist 1.5
#define SphereTreshold .6
#define SphereMaxOffset 1.
#define SphereMaxRadius .5
#define SphereOffsetSpeed 1.

#define CamPos vec3(-iTime * .2, -iTime, -iTime * .1)

// from Dave_Hoskins (https://www.shadertoy.com/view/4djSRW)
vec4 hash43(vec3 p)
{
	vec4 p4 = fract(vec4(p.xyzx)  * vec4(.1031, .1030, .0973, .1099));
    p4 += dot(p4, p4.wzxy+33.33);
    return fract((p4.xxyz+p4.yzzw)*p4.zywx);
}
